-- Decisions, deals, and config entries (T304), generated by Prisma from schema.prisma, plus the
-- rules Prisma cannot express, hand-written at the end: one active deal per package, a reason on
-- a fallen-through deal and a deadline on a pending one, decisions that name their offer and are
-- append-only, one live offer per investor (now over every live status), and closed packages
-- freeing their address.

-- CreateEnum
CREATE TYPE "RevisionAuthor" AS ENUM ('INVESTOR', 'AGENT');

-- CreateEnum
CREATE TYPE "DecisionType" AS ENUM ('ACCEPT', 'COUNTER', 'DECLINE_ALL');

-- CreateEnum
CREATE TYPE "DealStatus" AS ENUM ('PENDING_RECONFIRMATION', 'OFFER_ACCEPTED', 'UNDER_CONTRACT', 'INSPECTION', 'CLOSING', 'CLOSED', 'FELL_THROUGH', 'RECONFIRM_DECLINED');

-- AlterTable
ALTER TABLE "OfferRevision" ADD COLUMN     "author" "RevisionAuthor" NOT NULL DEFAULT 'INVESTOR';

-- CreateTable
CREATE TABLE "Decision" (
    "id" TEXT NOT NULL,
    "packageId" TEXT NOT NULL,
    "round" INTEGER NOT NULL,
    "type" "DecisionType" NOT NULL,
    "offerId" TEXT,
    "actorUserId" TEXT NOT NULL,
    "note" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "Decision_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "Deal" (
    "id" TEXT NOT NULL,
    "packageId" TEXT NOT NULL,
    "offerId" TEXT NOT NULL,
    "status" "DealStatus" NOT NULL,
    "fellThroughReason" TEXT,
    "promotedFromBackup" BOOLEAN NOT NULL DEFAULT false,
    "reconfirmBy" TIMESTAMP(3),
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Deal_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ConfigEntry" (
    "key" TEXT NOT NULL,
    "value" JSONB NOT NULL,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ConfigEntry_pkey" PRIMARY KEY ("key")
);

-- CreateIndex
CREATE INDEX "Decision_packageId_idx" ON "Decision"("packageId");

-- CreateIndex
CREATE UNIQUE INDEX "Deal_offerId_key" ON "Deal"("offerId");

-- CreateIndex
CREATE INDEX "Deal_packageId_idx" ON "Deal"("packageId");

-- AddForeignKey
ALTER TABLE "Decision" ADD CONSTRAINT "Decision_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "ListingPackage"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Deal" ADD CONSTRAINT "Deal_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "ListingPackage"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Deal" ADD CONSTRAINT "Deal_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "Offer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;




-- CreateIndex (hand-written): one active deal per package (FR-053). Accept inserts the deal first,
-- so a second, concurrent accept waits on this index and then fails; a final deal no longer counts.
CREATE UNIQUE INDEX "Deal_one_active_per_package" ON "Deal"("packageId")
    WHERE status NOT IN ('CLOSED', 'FELL_THROUGH', 'RECONFIRM_DECLINED');

-- AddCheck (hand-written): a fallen-through deal records why (FR-056), and a promoted backup has
-- its reconfirmation deadline (FR-057).
ALTER TABLE "Deal" ADD CONSTRAINT "Deal_fellThroughReason_check"
    CHECK (status <> 'FELL_THROUGH' OR "fellThroughReason" IS NOT NULL);
ALTER TABLE "Deal" ADD CONSTRAINT "Deal_reconfirmBy_check"
    CHECK (status <> 'PENDING_RECONFIRMATION' OR "reconfirmBy" IS NOT NULL);

-- AddCheck (hand-written): an accept and a counter name the offer they act on.
ALTER TABLE "Decision" ADD CONSTRAINT "Decision_offer_check"
    CHECK (type = 'DECLINE_ALL' OR "offerId" IS NOT NULL);

-- CreateTrigger (hand-written): decisions are history.
CREATE TRIGGER "Decision_append_only" BEFORE UPDATE OR DELETE ON "Decision"
    FOR EACH ROW EXECUTE FUNCTION "refuse_append_only_change"();

-- ReplaceIndex (hand-written): one live offer per investor per package per round (FR-042); a
-- countered, backup, or accepted offer is still live.
DROP INDEX "Offer_one_active_per_investor";
CREATE UNIQUE INDEX "Offer_one_live_per_investor" ON "Offer"("packageId", "investorId", "round")
    WHERE status IN ('ACTIVE', 'COUNTERED', 'BACKUP', 'ACCEPTED');

-- ReplaceIndex (hand-written): one active package per address (FR-013); a closed package frees
-- the address like a withdrawn one.
DROP INDEX "ListingPackage_one_active_per_address";
CREATE UNIQUE INDEX "ListingPackage_one_active_per_address" ON "ListingPackage"("addressHash")
    WHERE status NOT IN ('CLOSED', 'WITHDRAWN');
